from pathlib import Path
from fractions import Fraction
import json
from PIL import Image, ImageDraw, ImageFont, ImageOps

root=Path(__file__).resolve().parents[1]
records=json.loads((root/'docs/asset-audit.json').read_text())
total=sum(r['bytes'] for r in records)
web=sum(p.stat().st_size for p in (root/'assets/videos').glob('*.mp4'))
lines=['# Asset audit — Daniel Rawda','', 'Audited 9 November 2026. All 19 files in `E:\\PortfolioVideos` were inspected recursively using ffprobe. Three representative frames per video were extracted and visually reviewed. No dedicated showreel or résumé was present in that folder. The separately supplied résumé and portrait were used.','', '## Video inventory','', '| Original file | Duration | Original dimensions | Aspect ratio | Frame rate | Source size | Delivery copy |','|---|---:|---|---|---:|---:|---|']
for r in records:
    stem=Path(r['source']).stem.lower()
